    /// Edits existing chat folder. Returns information about the edited chat folder
    /// </summary>
    public Task<TdLib.TdApi.Objects.ChatFolderInfo> EditChatFolderAsync(int chatFolderId = default, ChatFolder folder = default)
    {

           using var activity =  StartCallActivity("EditChatFolderAsync", typeof(EditChatFolder).FullName ?? "EditChatFolderAsync");

           try
           {
             return client.EditChatFolderAsync(chatFolderId, folder);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
